    vec3 d = vec3(0.3,0.0,0.0);

    return (a + b*cos(TWOPI*(c*t + d)));
}

vec2 square(vec2 uv)
{
    return vec2(uv.x*uv.x - uv.y*uv.y, 2.0*uv.x*uv.y);
}

vec2 cube(vec2 uv)
{
    return vec2(uv.x*uv.x*uv.x - 3.0*uv.x*uv.y*uv.y , 3.0*uv.x*uv.x*uv.y - uv.y*uv.y*uv.y);
}

vec2 rotate(vec2 uv, float angle)
{
    float cosine = cos(angle); float sine = sin(angle);
    return (vec2(cosine*uv.x - sine*uv.y, sine*uv.x + cosine*uv.y));
}

float n = 3.0;

vec3 colorroot(float t, float k)
{
    float r = mod(k,3.0);
    if (r == 0.0){return(palette1(t));}
    else if(r == 1.0){return(palette2(t));}
    else {return(palette3(t));}
}

vec3 colorunity(float t, vec2 znext, float p)
{
    for (int k = 0; k < int(p); k++)
    {
        if (norm(znext - exp2d(vec2(0.0,TWOPI*float(k)/p))) < 0.1)
        {
            return(colorroot(t,float(k)));
        }
    }
}

vec3 colorgeneral(float t, vec2 znext)
{
    vec3 col;
    float iterationCount = t;
    float scale = 8.0;
    if (znext.x > 0.0 && znext.y > 0.0){col = palette1(sqrt(float(iterationCount) + 2.0*norm(znext))/scale);}
    else if (znext.x > 0.0 && znext.y < 0.0){col = palette2(sqrt(float(iterationCount) + 2.0*norm(znext))/scale);}
    else if (znext.x < 0.0 && znext.y > 0.0){col = palette3(sqrt(float(iterationCount) + 2.0*norm(znext))/scale);}
    else if (znext.x < 0.0 && znext.y < 0.0){col = palette4(sqrt(float(iterationCount) + 2.0*norm(znext))/scale);}  
    return(col);
}

vec2 function(vec2 uv, vec2 c)
{
    //return( power(uv,3.0) + times((c-vec2(1.0,0.0)),uv) - c );
    float remainder = 0.0;
    return (remainder*sin2d(uv) - (1.0-remainder)*power(uv,4.0) + c);
}

vec2 dfunction(vec2 uv,vec2 c)
{
    //return(3.0*power(uv,2.0) + c - vec2(1.0,0.0));
    float remainder = 0.0;
    return(remainder*cos2d(uv) - 4.0*(1.0-remainder)*power(uv,3.0));
}

vec2 newtonIteration(vec2 uv, vec2 c)
{
    vec2 a = vec2(1.8 - min(0.8,iTime/10.0));
    uv = uv - a*times(function(uv,c),oneoverz(dfunction(uv,c)));
    return(uv);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = (fragCoord/iResolution.xy - 0.5)*300.0;
    uv *= pow(10.0, (-1.5 + 0.4*cos(iTime*5.0))*min(max(iTime-9.0,0.0),1.0));
    uv += vec2(0.0, 0.0);
    uv = rotate(uv,max(iTime-8.0,0.0)*2.0);
    vec2 zcurrent = uv;
    float tolerance1 = pow(10.0,-10.0);
    float tolerance2 = pow(10.0,-10.0);
    vec2 znext = zcurrent;
    float norm2 = 1.0;
    int maxIteration = 1000;
    int iterationCount = 0;
    //vec2 c = (iMouse.xy/iResolution.xy - 0.5)*8.0;
    vec2 c = oneoverz(uv);
    while((norm(function(zcurrent,c)) > tolerance1) && (iterationCount <= maxIteration) )
    {
        zcurrent = znext;
        znext = newtonIteration(zcurrent,c);
        norm2 = norm(znext - zcurrent);
        iterationCount += 1;
    }

    vec3 col;
    if(norm2 < tolerance2)
    {
        // for roots of unity:
        //col = colorunity(float(iterationCount),znext,n);
        // for anything else whose roots we dont know at first (i cba):
        //col = colorgeneral(float(iterationCount), znext);
        float scale = 20.0;
        col = palette5(float(iterationCount)/scale);
    }

    else{col = vec3(0.0);}


    fragColor = vec4(col,1.0);
}
